from solution import merge_intervals

def test_basic():
    assert merge_intervals([[1,3],[2,6],[8,10]]) == [[1,6],[8,10]]

def test_single():
    assert merge_intervals([[1,4]]) == [[1,4]]

def test_non_overlapping():
    assert merge_intervals([[1,2],[3,4],[5,6]]) == [[1,2],[3,4],[5,6]]

def test_unsorted():
    assert merge_intervals([[5,8],[1,3]]) == [[1,3],[5,8]]

def test_contained():
    assert merge_intervals([[1,10],[2,5],[6,9]]) == [[1,10]]

from solution import first_missing_positive

def test_example1():
    assert first_missing_positive([3,4,-1,1]) == 2

def test_example2():
    assert first_missing_positive([1,2,0]) == 3

def test_all_negative():
    assert first_missing_positive([-5,-3,-1]) == 1

def test_consecutive():
    assert first_missing_positive([1,2,3,4,5]) == 6

def test_gap():
    assert first_missing_positive([7,8,9]) == 1

from solution import can_jump

def test_example1():
    assert can_jump([2,3,1,1,4]) is True

def test_example2():
    assert can_jump([3,2,1,0,4]) is False

def test_single():
    assert can_jump([0]) is True

def test_large_jump():
    assert can_jump([5,0,0,0,0,0]) is True

def test_trapped():
    assert can_jump([1,0,1,0]) is False
